package com.zxl.zxlaiagent.security;
import org.junit.jupiter.api.*;
import java.sql.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;
/** Deterministic two-connection PostgreSQL lock/expiry regressions. */
class SecurityConcurrencyPgTest extends AuthenticationPgTest {
 ActorRef ref; AuthorizationService policy; ExecutorService workers;
 @BeforeEach void actor(){ref=auth.login(subject,"synthetic-password",tenant).actor().ref();policy=new AuthorizationService(db);workers=Executors.newSingleThreadExecutor();}
 @AfterEach void stop(){workers.shutdownNow();}
 private void awaitWaiter(Connection holder)throws Exception{int pid;try(var s=holder.createStatement();var r=s.executeQuery("SELECT pg_backend_pid()")){r.next();pid=r.getInt(1);}long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(2);while(System.nanoTime()<deadline){try(var clear=holder.createStatement()){clear.execute("SELECT pg_stat_clear_snapshot()");}try(var s=SecurityDatabase.statement(holder,"SELECT count(*) FROM pg_stat_activity WHERE ? = ANY(pg_blocking_pids(pid))",pid);var r=s.executeQuery()){r.next();if(r.getInt(1)>0)return;}Thread.sleep(10);}fail("Expected a real PostgreSQL lock waiter");}
 private <T>Future<T> blockPastExpiry(Callable<T> action){return db.tx(c->{AuthenticationService.lockEpoch(c,ref);var future=workers.submit(action);try{awaitWaiter(c);Thread.sleep(1000);}catch(Exception e){throw new RuntimeException(e);}return future;});}
 private void shortSession(){db.tx(c->{try(var s=SecurityDatabase.statement(c,"UPDATE auth_session SET expires_at=clock_timestamp()+interval '700 milliseconds' WHERE session_id=?",ref.sessionId())){s.executeUpdate();}return null;});}
 @Test void resolveRejectsSessionThatExpiresWhileWaitingForEpoch()throws Exception{shortSession();var future=blockPastExpiry(()->auth.resolve(ref));assertInstanceOf(SecurityFailure.class,assertThrows(ExecutionException.class,()->future.get(5,TimeUnit.SECONDS)).getCause());}
 @Test void decisionRejectsSessionThatExpiresWhileWaitingForEpoch()throws Exception{shortSession();var future=blockPastExpiry(()->policy.decide(ref,"knowledge.read",ResourceRef.tenant(),Phase.PUBLISH,null));assertFalse(future.get(5,TimeUnit.SECONDS).allowed());}
 @Test void ticketRejectsExpiryThatOccursWhileWaitingForEpoch()throws Exception{var tickets=new ServiceCallAuthorizer(db,policy);String digest=ServiceCallAuthorizer.requestHash("GET","/documents",new byte[0]);String ticket=tickets.issue(ref,"worker","knowledge.read",ResourceRef.tenant(),digest,java.time.Duration.ofMillis(700));var future=blockPastExpiry(()->tickets.consume(ticket,"worker","knowledge.read",digest));assertInstanceOf(SecurityFailure.class,assertThrows(ExecutionException.class,()->future.get(5,TimeUnit.SECONDS)).getCause());}
 @Test void loginEvictionAndRevokeUseEpochBeforeSessionLocks()throws Exception{for(int i=0;i<4;i++)auth.login(subject,"synthetic-password",tenant);var login=db.tx(c->{AuthenticationService.lockEpoch(c,ref);var future=workers.submit(()->auth.login(subject,"synthetic-password",tenant));try{awaitWaiter(c);}catch(Exception e){throw new RuntimeException(e);}try(var s=SecurityDatabase.statement(c,"UPDATE auth_session SET revoked_at=clock_timestamp(),version=version+1 WHERE session_id=?",ref.sessionId())){s.executeUpdate();}return future;});assertNotNull(login.get(5,TimeUnit.SECONDS));}
  @Test void loginCapIsPerSubjectAndTenant(){String otherTenant=tenant+"-cap";db.tx(c->{try(var s=SecurityDatabase.statement(c,"INSERT INTO tenant(tenant_id) VALUES (?)",otherTenant)){s.executeUpdate();}try(var s=SecurityDatabase.statement(c,"INSERT INTO membership(tenant_id,subject_id,role) VALUES (?,?,'employee')",otherTenant,subject)){s.executeUpdate();}try(var s=SecurityDatabase.statement(c,"INSERT INTO authorization_epoch(tenant_id,subject_id) VALUES (?,?)",otherTenant,subject)){s.executeUpdate();}return null;});try{var other=auth.login(subject,"synthetic-password",otherTenant).actor().ref();for(int i=0;i<4;i++)auth.login(subject,"synthetic-password",tenant);assertEquals(subject,auth.resolve(ref).subjectId());assertEquals(otherTenant,auth.resolve(other).tenantId());auth.login(subject,"synthetic-password",tenant);assertThrows(SecurityFailure.class,()->auth.resolve(ref));assertEquals(otherTenant,auth.resolve(other).tenantId());}finally{db.tx(c->{try(var s=SecurityDatabase.statement(c,"DELETE FROM tenant WHERE tenant_id=?",otherTenant)){s.executeUpdate();}return null;});}}
 @Test void sameResourceIdCannotCrossTenant(){String otherTenant=tenant+"-b";db.tx(c->{try(var s=SecurityDatabase.statement(c,"INSERT INTO tenant(tenant_id) VALUES (?)",otherTenant)){s.executeUpdate();}try(var s=SecurityDatabase.statement(c,"INSERT INTO membership(tenant_id,subject_id,role) VALUES (?,?,'employee')",otherTenant,subject)){s.executeUpdate();}try(var s=SecurityDatabase.statement(c,"INSERT INTO authorization_epoch(tenant_id,subject_id) VALUES (?,?)",otherTenant,subject)){s.executeUpdate();}return null;});try{var resource=new ResourceRef("conversation","private-"+subject);policy.registerResource(ref,resource);var other=auth.login(subject,"synthetic-password",otherTenant).actor().ref();assertFalse(policy.decide(other,"conversation.readOwn",resource,Phase.HISTORY_READ,null).allowed());}finally{db.tx(c->{try(var s=SecurityDatabase.statement(c,"DELETE FROM tenant WHERE tenant_id=?",otherTenant)){s.executeUpdate();}return null;});}}
}
